-- New lifecycle templates join the managed pack automatically.
do $$declare d text;begin
 d:=pg_get_functiondef('private.whatsapp_event_field_allowed(text,text)'::regprocedure);
 d:=replace(d,'''order_ready'',''order_served''','''order_ready'',''order_serving'',''order_served''');execute d;
end $$;
alter table public.whatsapp_default_templates add column previous_template_id uuid references public.message_templates(id),add column template_version integer not null default 1;
create or replace function private.whatsapp_default_slots()returns jsonb language sql immutable set search_path=''as $$select '[{"key":"booking_confirmed","event":"booking_confirmed","kind":"event","delay":0,"activate":true},{"key":"booking_changed","event":"booking_changed","kind":"event","delay":0,"activate":true},{"key":"booking_cancelled","event":"booking_cancelled","kind":"event","delay":0,"activate":true},{"key":"checked_in","event":"checked_in","kind":"event","delay":0,"activate":true},{"key":"checked_out","event":"checked_out","kind":"event","delay":0,"activate":true},{"key":"arrival_reminder","event":"arrival_reminder","kind":"event","delay":180,"activate":true},{"key":"checkout_reminder","event":"checkout_reminder","kind":"event","delay":120,"activate":true},{"key":"review_request","event":"review_request","kind":"event","delay":0,"activate":false},{"key":"order_placed","event":"order_placed","kind":"event","delay":0,"activate":true},{"key":"order_preparing","event":"order_preparing","kind":"event","delay":0,"activate":true},{"key":"order_ready","event":"order_ready","kind":"event","delay":0,"activate":true},{"key":"order_served","event":"order_served","kind":"event","delay":0,"activate":true},{"key":"order_cancelled","event":"order_cancelled","kind":"event","delay":0,"activate":true},{"key":"request_received","event":"request_received","kind":"event","delay":0,"activate":true},{"key":"request_started","event":"request_started","kind":"event","delay":0,"activate":true},{"key":"request_completed","event":"request_completed","kind":"event","delay":0,"activate":true},{"key":"request_cancelled","event":"request_cancelled","kind":"event","delay":0,"activate":true},{"key":"payment_received","event":"payment_received","kind":"event","delay":0,"activate":true},{"key":"payment_refunded","event":"payment_refunded","kind":"event","delay":0,"activate":true},{"key":"invoice_issued","event":"invoice_issued","kind":"event","delay":0,"activate":true},{"key":"documents_received","event":"documents_received","kind":"event","delay":0,"activate":true},{"key":"documents_approved","event":"documents_approved","kind":"event","delay":0,"activate":true},{"key":"documents_rejected","event":"documents_rejected","kind":"event","delay":0,"activate":true},{"key":"order_feedback","event":"order_feedback","kind":"event","delay":20,"activate":true},{"key":"request_feedback","event":"request_feedback","kind":"event","delay":5,"activate":true},{"key":"order_serving","event":"order_serving","kind":"event","delay":0,"activate":true},{"key":"booking_deposit_requested","event":"booking_deposit_requested","kind":"event","delay":0,"activate":true},{"key":"booking_deposit_paid","event":"booking_deposit_paid","kind":"event","delay":0,"activate":true},{"key":"booking_payment_expired","event":"booking_payment_expired","kind":"event","delay":0,"activate":true},{"key":"booking_payment_failed","event":"booking_payment_failed","kind":"event","delay":0,"activate":true},{"key":"menu_stay","label":"My stay","group":"My stay","action":"reply","body":"Here are the details recorded for your stay at {{hotel_name}}. Your booking reference is {{booking_reference}}, and your assigned room is {{room_name}}. Your scheduled check-in date is {{check_in}}, and your check-out date is {{check_out}}. Please review these details before travelling. Reply Hi to open the guest menu or contact reception if any booking detail needs attention.","native_action":"stay","kind":"menu","activate":true},{"key":"menu_documents","label":"Upload documents","group":"My stay","action":"reply","body":"Hello {{guest_name}}, upload documents for booking {{booking_reference}} securely: {{portal_url}}. The hotel will confirm review here. Please do not send identity files into this chat.","native_action":"documents","kind":"menu","activate":true},{"key":"menu_checkin","label":"Check in","group":"My stay","action":"reply","body":"Hello {{guest_name}}, let us review check-in for booking {{booking_reference}} at {{hotel_name}}. Documents must be approved and your room must be ready before you confirm.","native_action":"checkin","kind":"menu","activate":true},{"key":"menu_checkout","label":"Check out","group":"My stay","action":"reply","body":"Hello {{guest_name}}, let us prepare checkout for booking {{booking_reference}} at {{hotel_name}}. Your bill and unfinished orders are checked before checkout confirmation.","native_action":"checkout","kind":"menu","activate":true},{"key":"menu_bill","label":"My bill","group":"My stay","action":"reply","body":"Hello {{guest_name}}, your private bill for booking {{booking_reference}} is here: {{portal_url}}. Contact reception if you need help.","native_action":"bill","kind":"menu","activate":true},{"key":"menu_food","label":"Order food","group":"Food & services","action":"reply","body":"Hello {{guest_name}}, choose food for your stay at {{hotel_name}} here: {{portal_url}}. Order confirmation and delivery updates will arrive on WhatsApp.","native_action":"food","kind":"menu","activate":true},{"key":"menu_services","label":"Request a service","group":"Food & services","action":"reply","body":"Hello {{guest_name}}, choose the help you need at {{hotel_name}}. No service request is placed until you confirm the details here on WhatsApp.","native_action":"services","kind":"menu","activate":true},{"key":"menu_location","label":"Hotel location","group":"Hotel information","action":"reply","body":"Here are the directions to {{hotel_name}}. Use the directions button to plan your arrival. Reception can help if you need assistance.","native_action":"location","kind":"menu","activate":true},{"key":"menu_photos","label":"Hotel photos","group":"Hotel information","action":"reply","body":"Here are some photos of {{hotel_name}} to help you recognise the hotel and plan your visit. Send Hi for more help.","native_action":"photos","kind":"menu","activate":true},{"key":"menu_website","label":"Hotel website","group":"Hotel information","action":"reply","body":"Visit the website of {{hotel_name}} using the button below. Reception can help with any questions about your stay.","native_action":"website","kind":"menu","activate":true},{"key":"menu_review","label":"Leave a review","group":"Hotel information","action":"reply","body":"Thank you for visiting {{hotel_name}}. You are welcome to share an honest review of your experience using the button below.","native_action":"review","kind":"menu","activate":true},{"key":"menu_reception","label":"Talk to reception","group":"Reception","action":"reception","body":"Thank you for contacting {{hotel_name}}. Reception has been notified and a team member will reply here. Automatic chat replies pause during staff handling.","native_action":"reception","kind":"menu","activate":true}]'::jsonb$$;
alter function public.whatsapp_automation_catalog()rename to whatsapp_automation_catalog_before_deposits;
revoke all on function public.whatsapp_automation_catalog_before_deposits()from public,anon,authenticated,service_role;
create function public.whatsapp_automation_catalog()returns jsonb language sql immutable set search_path=''as $$select public.whatsapp_automation_catalog_before_deposits()||'[{"key":"order_serving","label":"Food is being served / delivered","group":"Dining","scheduled":false},{"key":"booking_deposit_requested","label":"Booking deposit requested","group":"Reservations","scheduled":false},{"key":"booking_deposit_paid","label":"Booking deposit received","group":"Reservations","scheduled":false},{"key":"booking_payment_expired","label":"Booking payment hold expired","group":"Reservations","scheduled":false},{"key":"booking_payment_failed","label":"Booking payment needs attention","group":"Reservations","scheduled":false}]'::jsonb$$;
revoke all on function public.whatsapp_automation_catalog()from public,anon;grant execute on function public.whatsapp_automation_catalog()to authenticated,service_role;

-- Approval waiting is distinct from an owner explicitly turning a rule off.
create function private.whatsapp_managed_event_waiting(p_property uuid,p_event text)returns boolean language sql stable security definer set search_path=''as $$
 select exists(select 1 from public.whatsapp_default_setup cfg join public.whatsapp_default_templates dt on dt.property_id=cfg.property_id left join public.whatsapp_automation_rules r on r.property_id=cfg.property_id and r.event_key=dt.event_key where cfg.property_id=p_property and cfg.configured_by is not null and cfg.enabled and dt.event_key=p_event and dt.state in('queued','awaiting_approval','needs_attention')and(r.id is null or r.version=dt.rule_version)and exists(select 1 from jsonb_array_elements(private.whatsapp_default_slots())x where x->>'event'=p_event and x->>'activate'='true'))
$$;
revoke all on function private.whatsapp_managed_event_waiting(uuid,text)from public,anon,authenticated,service_role;
do $$declare d text;begin
 d:=pg_get_functiondef('private.capture_whatsapp_event(uuid,uuid,text,text,text,uuid,text,jsonb,timestamptz,timestamptz)'::regprocedure);
 d:=replace(d,'exists(select 1 from public.whatsapp_automation_rules where property_id=p_property and event_key=p_event)or','exists(select 1 from public.whatsapp_automation_rules where property_id=p_property and event_key=p_event)and not private.whatsapp_managed_event_waiting(p_property,p_event)or');execute d;
 d:=pg_get_functiondef('private.whatsapp_native_event_error(uuid)'::regprocedure);
 d:=replace(d,'not rule.enabled or e.rule_id','not rule.enabled and not private.whatsapp_managed_event_waiting(e.property_id,e.event_key)or e.rule_id');execute d;
 d:=pg_get_functiondef('private.apply_whatsapp_default_assignments(uuid)'::regprocedure);
 d:=replace(d,'r.template_id is distinct from t.id or slot.rule_version is null','r.template_id is distinct from t.id and r.template_id is distinct from slot.previous_template_id or slot.rule_version is null');
 -- Don't turn a managed pending template into an explicit off rule.
 d:=replace(d,'keys:=t.parameter_names;desired:=',E'if t.provider_status<>''APPROVED''or not t.automation_supported then all_ready:=false;continue;end if;\n keys:=t.parameter_names;desired:=');execute d;
end $$;
-- Add missing slots to every connected hotel without resetting its settings.
insert into public.whatsapp_default_templates(property_id,slot,name,kind,event_key)
 select cfg.property_id,x->>'key','hp_'||replace(cfg.property_id::text,'-','')||'_'||(x->>'key')||'_v1',x->>'kind',x->>'event'from public.whatsapp_default_setup cfg cross join lateral jsonb_array_elements(private.whatsapp_default_slots())x on conflict do nothing;
-- Replace managed wording only. Custom templates and explicit rule edits stay untouched.
update public.whatsapp_default_templates d set previous_template_id=d.template_id,template_id=null,provider_id=null,template_version=2,name=regexp_replace(d.name,'_v1$','_v2'),state='queued',last_error=null
 where d.slot in('booking_changed','checked_in','arrival_reminder','checkout_reminder','documents_approved','menu_stay')and d.state<>'customized'and d.template_version=1 and not exists(select 1 from public.whatsapp_automation_rules r where r.property_id=d.property_id and r.event_key=d.event_key and r.version is distinct from d.rule_version);
update public.whatsapp_default_setup set next_check_at=now()where configured_by is not null;
